import itertools

# GF(3) arithmetic mod 3
def add(a, b):
    return tuple((x + y) % 3 for x, y in zip(a, b))

def sub(a, b):
    return tuple((x - y) % 3 for x, y in zip(a, b))

def mul(k, v):
    return tuple((k * x) % 3 for x in v)

# Points of AG(3,3)
points = [(x, y, z) for x in range(3) for y in range(3) for z in range(3)]
point_to_idx = {p: i for i, p in enumerate(points)}

# Nonzero vectors (directions)
nonzero_vectors = [(x, y, z) for x in range(3) for y in range(3) for z in range(3) if not (x == 0 and y == 0 and z == 0)]

# Group directions into classes: d and 2d are same direction
seen = set()
directions = []
for v in nonzero_vectors:
    if v not in seen:
        directions.append(v)
        seen.add(v)
        seen.add(mul(2, v))

print("Number of directions:", len(directions))  # should be 13

# For each direction, construct parallel class
parallel_classes = []
for d in directions:
    used = set()
    groups = []
    for p in points:
        if p in used:
            continue
        # line: p, p+d, p+2d
        q = add(p, d)
        r = add(q, d)  # p+2d
        group = [p, q, r]
        for pt in group:
            used.add(pt)
        groups.append(group)
    parallel_classes.append(groups)

print("Number of parallel classes:", len(parallel_classes))

# Verify each parallel class partitions the 27 points into 9 triples
for i, pc in enumerate(parallel_classes):
    all_pts = []
    for g in pc:
        all_pts.extend(g)
    assert set(all_pts) == set(points), f"PC {i} doesn't partition"
    assert len(pc) == 9

# Verify the whole design: no pair appears in more than one block
pair_to_blocks = {}
for pc_idx, pc in enumerate(parallel_classes):
    for g in pc:
        for pair in itertools.combinations(g, 2):
            pair_sorted = tuple(sorted(pair))
            if pair_sorted not in pair_to_blocks:
                pair_to_blocks[pair_sorted] = []
            pair_to_blocks[pair_sorted].append((pc_idx, g))

max_count = max(len(v) for v in pair_to_blocks.values())
print("Max pair occurrence:", max_count)

# If max_count == 1, we have a valid Steiner triple system.
# Now produce a schedule for 7 weeks using first 7 parallel classes.
num_weeks = 7
num_golfers = 27
num_groups = 9

# We'll output flat list: entry w*27 + p = group index (0..8) of golfer p in week w
schedule = []
for w in range(num_weeks):
    pc = parallel_classes[w]
    # We need to assign group numbers 0..8 to the 9 triples.
    # Just assign in order
    # For each golfer (by index), find which group they belong to
    golfer_group = {}
    for g_idx, group in enumerate(pc):
        for pt in group:
            idx = point_to_idx[pt]
            golfer_group[idx] = g_idx
    for p in range(num_golfers):
        schedule.append(golfer_group[p])

print("Schedule length:", len(schedule))
print("First 54 entries (2 weeks):", schedule[:54])

# Verify no pair appears more than once in these 7 weeks
pair_weeks = {}
for w in range(num_weeks):
    for g_idx in range(num_groups):
        # Get golfers in this group this week
        golfers_in_group = [p for p in range(num_golfers) if schedule[w*27 + p] == g_idx]
        assert len(golfers_in_group) == 3
        for pair in itertools.combinations(golfers_in_group, 2):
            pair_sorted = tuple(sorted(pair))
            if pair_sorted not in pair_weeks:
                pair_weeks[pair_sorted] = []
            pair_weeks[pair_sorted].append(w)

max_pair = max(len(v) for v in pair_weeks.values())
print("Max pair in 7 weeks:", max_pair)
print("Total pairs:", len(pair_weeks))
# Should be (27 choose 2) = 351
print("Expected pairs:", 27*26//2)

import itertools

# GF(3) arithmetic mod 3
def add(a, b):
    return tuple((x + y) % 3 for x, y in zip(a, b))

def mul(k, v):
    return tuple((k * x) % 3 for x in v)

# Points of AG(3,3)
points = [(x, y, z) for x in range(3) for y in range(3) for z in range(3)]
point_to_idx = {p: i for i, p in enumerate(points)}

# Nonzero directions (canonical)
nonzero_vectors = [(x, y, z) for x in range(3) for y in range(3) for z in range(3) if not (x == 0 and y == 0 and z == 0)]
seen = set()
directions = []
for v in nonzero_vectors:
    if v not in seen:
        directions.append(v)
        seen.add(v)
        seen.add(mul(2, v))

# Parallel classes
parallel_classes = []
for d in directions:
    used = set()
    groups = []
    for p in points:
        if p in used:
            continue
        q = add(p, d)
        r = add(q, d)
        group = [p, q, r]
        for pt in group:
            used.add(pt)
        groups.append(group)
    parallel_classes.append(groups)

# Build schedule for 7 weeks
schedule = []
for w in range(7):
    pc = parallel_classes[w]
    golfer_group = {}
    for g_idx, group in enumerate(pc):
        for pt in group:
            idx = point_to_idx[pt]
            golfer_group[idx] = g_idx
    for p in range(27):
        schedule.append(golfer_group[p])

print("Full schedule (189 ints):")
print(schedule)

# Verify constraints
# 1. Each week, 9 groups of 3
# 2. No pair repeated
pair_seen = set()
for w in range(7):
    group_to_golfers = {g: [] for g in range(9)}
    for p in range(27):
        group_to_golfers[schedule[w*27 + p]].append(p)
    for g, golfers in group_to_golfers.items():
        assert len(golfers) == 3, f"Week {w} group {g} has {len(golfers)} golfers"
        for pair in itertools.combinations(sorted(golfers), 2):
            assert pair not in pair_seen, f"Pair {pair} repeated at week {w}"
            pair_seen.add(pair)

print(f"Total distinct pairs: {len(pair_seen)}")
print("All constraints satisfied!")
